Input: {"question": "When was the Elks organization founded?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0498-1368798a59d2:d00", "start": 0, "end": 83, "text": "Elks of Canada Elks of Canada is a fraternal organization that was founded in 1912."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0498-1368798a59d2:d00", "start": 84, "end": 274, "text": "It is not directly affiliated with Benevolent and Protective Order of Elks, the American organization founded in 1868, but the two \"share a common history and enjoy a friendly relationship\"."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0498-1368798a59d2:d00", "start": 275, "end": 361, "text": "The organization was founded in Vancouver, British Columbia by three men from Seattle."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0498-1368798a59d2:d00", "start": 362, "end": 516, "text": "It appeared that they were only in it for the money, but early applicants were able to seize control of the organization and begin building it in earnest."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0498-1368798a59d2:d00", "start": 517, "end": 594, "text": "The first Grand Exalted Ruler of the Grand Lodge of Canada was Charles Edward"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0498-1368798a59d2:d01", "start": 0, "end": 89, "text": "\"It is usually gentle and even timorous, it is strong and valiant in defense of its own.\""}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0498-1368798a59d2:d01", "start": 90, "end": 124, "text": "Quoted from Denver Elks Lodge #17."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0498-1368798a59d2:d01", "start": 125, "end": 350, "text": "The early years of Denver Lodge found the group at various leased sites in and around downtown Denver since its founding in 1895 until 1912 when new permanent quarters were opened at the corner of 14th and California streets."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0498-1368798a59d2:d01", "start": 351, "end": 431, "text": "Beautiful and unique stained glass panels were installed in this Lodge building."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0498-1368798a59d2:d01", "start": 432, "end": 562, "text": "This old building was sold and most of the stained glass was transferred to the present quarters at 2475 West 26th Avenue in 1974."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0498-1368798a59d2:d02", "start": 0, "end": 115, "text": "The Benevolent and Protective Order of Elks of Canada is the largest all-Canadian fraternal organization in Canada."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0498-1368798a59d2:d02", "start": 116, "end": 253, "text": "Prior to 1868, the Benevolent and Protective Order of Elks of the United States of America had flourished and grown throughout the U.S.A."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0498-1368798a59d2:d02", "start": 254, "end": 412, "text": "The Benevolent and Protective Order of Elks of Canada are not affiliated with the American Elks, but share a common history and enjoy a friendly relationship."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0498-1368798a59d2:d02", "start": 413, "end": 536, "text": "In the U.S.A., the Elks began with a group of actors and entertainers led by Charles Algernon Sidney Vivian, an Englishman."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0498-1368798a59d2:d02", "start": 537, "end": 623, "text": "They chose the name \"Elks\" in 1868, marking the official founding of the organization."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0498-1368798a59d2:d03", "start": 0, "end": 228, "text": "Improved Benevolent and Protective Order of Elks of the World The Improved Benevolent Protective Order of Elks of the World or IBPOEW is an African-American fraternal order modeled on the Benevolent and Protective Order of Elks."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0498-1368798a59d2:d03", "start": 229, "end": 256, "text": "It was established in 1897."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0498-1368798a59d2:d03", "start": 257, "end": 400, "text": "In the early 21st century, with 500,000 members and 1500 lodges in the world, the IBPOEW claims to be the largest black fraternal organization."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0498-1368798a59d2:d03", "start": 401, "end": 605, "text": "The Order claims descent from the Free African Society, the first formal black society in America, founded in 1787 as a mutual aid society by Absalom Jones and Richard Allen in Philadelphia, Pennsylvania."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0498-1368798a59d2:d03", "start": 606, "end": 616, "text": "Its formal"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 0, "end": 16, "text": "founded in 1878."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 17, "end": 128, "text": "At the 1885 Grand Lodge it was reported that the EMBA was prosperous, but its finances were carelessly managed."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 129, "end": 279, "text": "The Association was disbanded after the 1907 Grand Lodge passed a resolution banning mutual or insurance features, as well as degrees and auxiliaries."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 280, "end": 410, "text": "Despite its 1907 resolution banning any auxiliaries, the Elks at one point had a youth affiliate for young men called the Antlers."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 411, "end": 486, "text": "The first chapter was organized in February 1922 by San Francisco Lodge #3."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0498-1368798a59d2:d04", "start": 487, "end": 609, "text": "The 1927 Grand Lodge approved the junior order, granting the Grand Exalted Ruler the power to permit subordinate lodges to"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 0, "end": 54, "text": "of charity , justice , brotherly love , and fidelity ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 55, "end": 315, "text": "Since its inception in the late 1800 ’ s , the BPOE has grown into one of the most respected organizations in the United States , and since the early 1900 ’ s , the Massachusetts Elks Association and its members have been proud to represent this organization ."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 316, "end": 363, "text": "There are over 1,700 lodges throughout the U.S."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 364, "end": 404, "text": "with over a million members nationally ."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 405, "end": 469, "text": "As Elks We : Pledge to Patriotism : Annual Flag Day Ceremonies ."}, "D6S6": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 470, "end": 515, "text": "Endless , evolving support for our Veterans ."}, "D6S7": {"document_number": 6, "doc_id": "ramdocs-0498-1368798a59d2:d05", "start": 516, "end": 535, "text": "Educate our Youth :"}, "D7S1": {"document_number": 7, "doc_id": "ramdocs-0498-1368798a59d2:d06", "start": 0, "end": 41, "text": "an Elk 's head represented on the front ."}, "D7S2": {"document_number": 7, "doc_id": "ramdocs-0498-1368798a59d2:d06", "start": 42, "end": 231, "text": "The use of the fez as the official headgear of the Benevolent and Protective Order of Elks of Canada began pursuant to a resolution passed at the 1925 convention held in Montreal , Canada ."}, "D7S3": {"document_number": 7, "doc_id": "ramdocs-0498-1368798a59d2:d06", "start": 232, "end": 352, "text": "The Royal Purple of Canada is the official women 's auxiliary to the Benevolent and Protective Order of Elks of Canada ."}, "D7S4": {"document_number": 7, "doc_id": "ramdocs-0498-1368798a59d2:d06", "start": 353, "end": 493, "text": "The Royal Purple was founded on September 11 , 1914 and is incorporated under a special Dominion of Canada Charter with the Elks of Canada ."}, "D7S5": {"document_number": 7, "doc_id": "ramdocs-0498-1368798a59d2:d06", "start": 494, "end": 533, "text": "The first Lodge was set up in Vancouver"}}, "original_cards": [{"doc_id": "ramdocs-0498-1368798a59d2:d00", "card_id": "ramdocs-0498-1368798a59d2:d00:c0", "entity": "Elks of Canada", "scope": "founding year", "claim": "Elks of Canada is a fraternal organization that was founded in 1912.", "answer": "1912", "quote": "Elks of Canada Elks of Canada is a fraternal organization that was founded in 1912.", "original_document_number": 1}, {"doc_id": "ramdocs-0498-1368798a59d2:d01", "card_id": "ramdocs-0498-1368798a59d2:d01:c0", "entity": "Denver Lodge", "scope": "Denver Elks Lodge #17", "claim": "The Denver Elks Lodge was founded in 1895.", "answer": "1895", "quote": "The early years of Denver Lodge found the group at various leased sites in and around downtown Denver since its founding in 1895 until 1912 when new permanent quarters were opened at the corner of 14th and California streets.", "original_document_number": 2}, {"doc_id": "ramdocs-0498-1368798a59d2:d02", "card_id": "ramdocs-0498-1368798a59d2:d02:c0", "entity": "Elks organization", "scope": "founding date", "claim": "The Elks organization was officially founded in 1868 when they chose the name \"Elks\".", "answer": "1868", "quote": "They chose the name \"Elks\" in 1868, marking the official founding of the organization.", "original_document_number": 3}, {"doc_id": "ramdocs-0498-1368798a59d2:d03", "card_id": "ramdocs-0498-1368798a59d2:d03:c0", "entity": "Improved Benevolent and Protective Order of Elks of the World", "scope": "founding date", "claim": "The Improved Benevolent and Protective Order of Elks of the World was established in 1897.", "answer": "1897", "quote": "Improved Benevolent and Protective Order of Elks of the World The Improved Benevolent Protective Order of Elks of the World or IBPOEW is an African-American fraternal order modeled on the Benevolent and Protective Order of Elks. It was established in 1897.", "original_document_number": 4}, {"doc_id": "ramdocs-0498-1368798a59d2:d04", "card_id": "ramdocs-0498-1368798a59d2:d04:c0", "entity": "Elks organization", "scope": "founding date", "claim": "The Elks organization was founded in 1878.", "answer": "1878", "quote": "founded in 1878.", "original_document_number": 5}, {"doc_id": "ramdocs-0498-1368798a59d2:d05", "card_id": "ramdocs-0498-1368798a59d2:d05:c0", "entity": "BPOE", "scope": "Elks organization", "claim": "The BPOE (Elks organization) was founded in the late 1800's.", "answer": "late 1800's", "quote": "Since its inception in the late 1800 ’ s , the BPOE has grown into one of the most respected organizations in the United States , and since the early 1900 ’ s , the Massachusetts Elks Association and its members have been proud to represent this organization .", "original_document_number": 6}], "current_answers": ["1868", "1878", "1897", "1912", "late 1800's", "1895"], "candidate_answers": [{"candidate_id": "R0", "answer": "1868", "origin": "initial"}, {"candidate_id": "R1", "answer": "1878", "origin": "initial"}, {"candidate_id": "R2", "answer": "1897", "origin": "initial"}, {"candidate_id": "R3", "answer": "1912", "origin": "initial"}, {"candidate_id": "R4", "answer": "late 1800's", "origin": "initial"}, {"candidate_id": "R5", "answer": "1895", "origin": "coverage_addition"}], "requested_slot_hint": "other"}
